@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&display=swap');
:root{--ink:#090c18;--panel:#111627;--line:#232b40;--muted:#75809a;--white:#f4f4f7;--cyan:#47f4db;--pink:#ff4e83;--yellow:#f9dd69;--font-display:'Barlow Condensed',Impact,sans-serif;--font-mono:'DM Mono',monospace}
*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 50% -12%,#1b2440 0,transparent 58%),#090c18;color:var(--white);font-family:var(--font-mono);padding:0 24px}.game-shell{max-width:1120px;margin:0 auto}.topbar{height:76px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(133,150,192,.13);margin-bottom:26px}.brand{display:flex;align-items:center;gap:11px;color:var(--white);font:800 21px var(--font-display);letter-spacing:1.3px;text-decoration:none}.brand-light{font-weight:500;color:#9da6b9;margin-left:4px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid var(--cyan);color:var(--cyan);font:800 23px var(--font-display);transform:skew(-8deg);box-shadow:0 0 15px #47f4db25}.season-tag{font-size:10px;letter-spacing:1.2px;color:#aab2c5;display:flex;align-items:center;gap:9px}.season-tag i{font-style:normal;color:#59637a;padding-left:9px;border-left:1px solid #333b4e}.live-dot{height:6px;width:6px;background:var(--pink);border-radius:50%;box-shadow:0 0 9px var(--pink)}.sound-toggle{border:1px solid #252d41;color:#9ea7ba;background:#101524;padding:9px 12px;display:flex;align-items:center;gap:8px;font:10px var(--font-mono);letter-spacing:.6px;cursor:pointer}.sound-toggle b{color:var(--cyan);font-weight:500}.sound-icon{font-size:16px;color:var(--cyan)}
.game-card{border:1px solid #283149;background:#0e1321;box-shadow:0 24px 70px #0005}.arena-top{height:92px;position:relative;background:linear-gradient(180deg,#12192a,#0f1422);display:grid;grid-template-columns:1fr 120px 1fr;align-items:start;padding:13px 22px 24px}.fighter-info{display:flex;align-items:center;gap:11px}.fighter-info strong{display:block;font:800 23px/22px var(--font-display);letter-spacing:1.4px}.fighter-info small{color:#7d879e;font-size:8px;letter-spacing:1.1px}.player-number,.cpu-badge{display:grid;place-items:center;height:28px;width:30px;font:700 11px var(--font-mono);color:var(--cyan);border:1px solid #47f4db4a;background:#47f4db10}.right-info{justify-content:flex-end;text-align:right}.cpu-badge{color:var(--pink);border-color:#ff4e834a;background:#ff4e8310}.fight-status{text-align:center;align-self:start;margin-top:-3px;position:relative;z-index:2}.round-label{display:block;color:#738099;font-size:8px;letter-spacing:1.4px}.round-label b{color:#b7bfd0;font-weight:400}.timer{font:800 31px/32px var(--font-display);color:#fff}.status-text{position:absolute;top:31px;left:50%;transform:translateX(-50%);white-space:nowrap;color:var(--yellow);font-size:8px;letter-spacing:1.5px}.health-track{position:absolute;height:13px;background:#252d40;top:52px;width:calc(50% - 93px);overflow:hidden;border:1px solid #343d52}.health-left{left:22px;transform:skew(-13deg);transform-origin:left}.health-right{right:22px;transform:skew(13deg);transform-origin:right}.health-fill{height:100%;width:100%;transition:width .24s;background:linear-gradient(90deg,#19bcae,var(--cyan));box-shadow:0 0 12px #47f4db6b;position:relative}.health-right .health-fill{margin-left:auto;background:linear-gradient(90deg,var(--pink),#ff8b79);box-shadow:0 0 12px #ff4e836b}.health-shine{position:absolute;inset:2px 2px auto;height:2px;background:#ffffff48}.meter-row{position:absolute;top:70px;display:flex;align-items:center;gap:7px;color:#68738a;font-size:7px;letter-spacing:1px}.meter-left{left:23px}.meter-right{right:23px;flex-direction:row-reverse}.meter-track{width:93px;height:4px;background:#252d40}.meter-track i{height:100%;display:block;width:0;background:var(--yellow);box-shadow:0 0 8px #f9dd69;transition:width .25s}.canvas-wrap{position:relative;background:#11182a;overflow:hidden}.canvas-wrap canvas{display:block;width:100%;height:auto;aspect-ratio:1000/520}.round-banner,.pause-overlay{position:absolute;inset:0;z-index:4;display:flex;align-items:center;justify-content:center;flex-direction:column;background:radial-gradient(ellipse at center,#10172ad9 0%,#080b16eF 75%);transition:opacity .35s,visibility .35s}.round-banner.hidden,.pause-overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.banner-kicker{font-size:9px;letter-spacing:3px;color:var(--cyan);margin:0 0 9px}.round-banner strong,.pause-overlay strong{font:900 clamp(54px,9vw,94px)/.9 var(--font-display);letter-spacing:4px;color:#f4f4f7;text-shadow:0 0 30px #47f4db38}.round-banner button{font:700 13px var(--font-display);letter-spacing:1.5px;padding:13px 23px;margin-top:24px;color:#071217;background:var(--cyan);border:0;clip-path:polygon(8px 0,100% 0,100% calc(100% - 8px),calc(100% - 8px) 100%,0 100%,0 8px);cursor:pointer;transition:transform .2s,box-shadow .2s}.round-banner button:hover{transform:translateY(-2px);box-shadow:0 5px 25px #47f4db66}.round-banner button span{font-size:17px;margin-left:9px}.round-banner #bannerSub{font-size:9px;letter-spacing:1.7px;color:#8490a8;margin-top:11px}.pause-overlay{background:#080b16be;gap:12px}.pause-overlay strong{font-size:64px;color:var(--yellow)}.pause-overlay span{font-size:10px;color:#a5aec1}.pause-overlay kbd{font-size:9px}.toast{position:absolute;left:50%;top:24%;transform:translate(-50%,-10px);font:800 38px var(--font-display);letter-spacing:2px;color:#fff;text-shadow:0 0 24px var(--yellow);opacity:0;pointer-events:none;z-index:3;transition:.18s}.toast.show{opacity:1;transform:translate(-50%,0)}.arena-footer{height:34px;display:flex;align-items:center;justify-content:space-between;padding:0 16px;color:#68738a;font-size:8px;letter-spacing:1px}.arena-footer b{color:#38445a}.tiny-spark{font-style:normal;color:var(--cyan);font-size:12px;margin-right:5px}.arena-footer #roundScore{color:#8e98ac}.arena-footer #roundScore b{color:#d8deea;font-weight:500}
.below-game{margin-top:24px}.controls-heading{display:flex;justify-content:space-between;align-items:center;font-size:9px;letter-spacing:1.5px;color:#d9deea}.control-tip{color:#78839b;font-size:8px;letter-spacing:.8px}.control-tip i{color:var(--cyan);font-style:normal;font-size:12px;margin-left:5px}.controls-grid{display:grid;grid-template-columns:1.35fr 1.2fr 1fr .85fr;border:1px solid #212a3d;margin-top:12px;background:#0e1321}.control-group{min-height:70px;display:flex;align-items:center;gap:10px;padding:10px 12px;border-right:1px solid #212a3d}.control-group:last-child{border:0}.group-icon{font-size:20px;color:var(--cyan);width:23px;text-align:center}.punch-icon{color:var(--pink)}.special-icon{color:var(--yellow)}.pause-icon{color:#9aa8c2}.control-keys{display:flex;gap:3px}.control-keys kbd{min-width:20px;height:21px;padding:0 5px;display:grid;place-items:center;border:1px solid #38445a;background:#171e30;color:#dbe0e9;font:10px var(--font-mono);box-shadow:0 2px #242d42}.control-keys .key-special{border-color:#978841;color:var(--yellow)}.control-copy b{display:block;font:700 13px var(--font-display);letter-spacing:.6px}.control-copy small{display:block;margin-top:3px;color:#78839b;font-size:8px;white-space:nowrap}.page-footer{display:flex;justify-content:space-between;padding:21px 2px;color:#525d73;font-size:8px;letter-spacing:1.2px}.page-footer b{color:var(--cyan);padding-left:6px}.mobile-controls{display:none}
@media(max-width:700px){body{padding:0 12px}.topbar{height:58px;margin-bottom:14px}.brand{font-size:18px}.season-tag{font-size:8px;gap:6px}.season-tag i{display:none}.sound-toggle{padding:7px}.arena-top{height:82px;padding:10px 12px 22px;grid-template-columns:1fr 62px 1fr}.fighter-info{gap:6px}.fighter-info strong{font-size:18px;line-height:18px}.fighter-info small{font-size:6px;letter-spacing:.6px}.player-number,.cpu-badge{height:23px;width:23px;font-size:8px}.health-track{top:48px;width:calc(50% - 58px)}.health-left{left:12px}.health-right{right:12px}.timer{font-size:25px;line-height:27px}.round-label{font-size:7px}.status-text{top:28px;font-size:7px}.meter-row{top:66px}.meter-left{left:12px}.meter-right{right:12px}.meter-track{width:65px}.canvas-wrap canvas{aspect-ratio:1000/520}.arena-footer{padding:0 9px;font-size:6px;letter-spacing:.5px;height:30px}.footer-center{display:none}.controls-heading{font-size:8px}.control-tip{font-size:7px}.controls-grid{grid-template-columns:1fr 1fr}.control-group{min-height:58px;padding:8px;gap:7px}.control-group:nth-child(2){border-right:0}.control-group:nth-child(-n+2){border-bottom:1px solid #212a3d}.control-copy b{font-size:12px}.control-copy small{font-size:7px}.control-keys kbd{min-width:18px;height:20px;font-size:9px}.group-icon{width:18px;font-size:17px}.page-footer{font-size:6px;letter-spacing:.7px}.mobile-controls{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:11px;touch-action:none}.touch-cluster{display:flex;gap:6px}.touch-cluster button{border:1px solid #343e56;background:#141b2d;color:#dce4f1;height:42px;min-width:42px;border-radius:6px;font:700 12px var(--font-display);touch-action:none;user-select:none}.touch-cluster button.active,.touch-cluster button:active{border-color:var(--cyan);color:var(--cyan);background:#47f4db16}.attack-touch button{min-width:54px;font-size:10px}.attack-touch .touch-special{color:var(--yellow);border-color:#756938}.below-game{margin-top:17px}.round-banner strong{font-size:55px}.banner-kicker{font-size:7px}.round-banner #bannerSub{font-size:7px}.round-banner button{font-size:11px;padding:11px 17px;margin-top:17px}}
@media(max-width:390px){body{padding:0 8px}.sound-toggle span:last-child{display:none}.control-tip{max-width:145px;text-align:right}.touch-cluster{gap:4px}.touch-cluster button{min-width:36px;height:39px}.attack-touch button{min-width:47px;font-size:9px}.control-group{gap:5px;padding:6px}.arena-footer{font-size:5.5px}}

(() => {
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const W = 1000, H = 520, FLOOR = 421;
  const ui = {
    h1: document.getElementById('health1'), h2: document.getElementById('health2'),
    m1: document.getElementById('meter1'), m2: document.getElementById('meter2'),
    timer: document.getElementById('timer'), status: document.getElementById('statusText'),
    banner: document.getElementById('roundBanner'), title: document.getElementById('bannerTitle'),
    sub: document.getElementById('bannerSub'), start: document.getElementById('startButton'),
    pause: document.getElementById('pauseOverlay'), toast: document.getElementById('toast'), score: document.getElementById('roundScore')
  };
  const keys = Object.create(null);
  let p1, p2, running = false, paused = false, matchOver = false, timeLeft = 60;
  let wins = [0, 0], roundNo = 1, last = 0, elapsed = 0, shake = 0, toastTimer = 0;
  let particles = [], audioCtx = null, soundOn = true;
  const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
  const fighter = (x, face, color, glow, name, human) => ({x, y:0, vx:0, vy:0, face, color, glow, name, human, hp:100, meter:0, grounded:true, action:'idle', actionT:0, cooldown:0, invuln:0, hurtT:0, block:false, walk:0, aiThink:0, aiMove:0, aiBlock:0});
  function resetRound() {
    p1 = fighter(295, 1, '#4df3dc', '#38ffe5', 'VOLT', true);
    p2 = fighter(705, -1, '#ff5488', '#ff4b80', 'GLITCH', false);
    p1.y = p2.y = 0; timeLeft = 60; particles = []; shake = 0;
    ui.h1.style.width = ui.h2.style.width = '100%';
    ui.m1.style.width = ui.m2.style.width = '0%'; ui.timer.textContent = '60';
    ui.status.textContent = 'FIGHT!'; updateScore();
  }
  resetRound();
  function updateScore(){ui.score.innerHTML = `ROUNDS <b>${wins[0]}</b> — <b>${wins[1]}</b>`;}
  function sound(freq=180, duration=.08, type='sine', volume=.04){
    if(!soundOn) return;
    try { audioCtx ||= new (window.AudioContext||window.webkitAudioContext)(); const o=audioCtx.createOscillator(), g=audioCtx.createGain(); o.type=type;o.frequency.setValueAtTime(freq,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(50,freq*.55),audioCtx.currentTime+duration);g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);} catch(_){ }
  }
  document.getElementById('soundToggle').addEventListener('click', e => {
    soundOn = !soundOn; e.currentTarget.querySelector('b').textContent = soundOn ? 'ON' : 'OFF';
    e.currentTarget.querySelector('.sound-icon').textContent = soundOn ? '♪' : '×';
    if(soundOn) sound(520,.07,'sine',.025);
  });
  function announce(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=.75;}
  function startGame(){
    if(matchOver){wins=[0,0];roundNo=1;matchOver=false;resetRound();ui.title.textContent='READY?';ui.sub.textContent='FIRST TO TWO ROUNDS';ui.start.innerHTML='ENTER THE ARENA <span>↗</span>';}
    ui.banner.classList.add('hidden'); running=true; paused=false; last=performance.now(); sound(370,.12,'triangle',.035); announce('FIGHT!');
  }
  ui.start.addEventListener('click', startGame);
  function togglePause(){if(!running||matchOver)return;paused=!paused;ui.pause.classList.toggle('hidden',!paused);if(!paused)last=performance.now();}
  window.addEventListener('keydown', e=>{
    const k=e.key.toLowerCase(); if([' ','arrowleft','arrowright','arrowup','arrowdown'].includes(k))e.preventDefault();
    if(k==='escape'){togglePause();return;} if(k==='enter'&&!running){startGame();return;} keys[k]=true;
    if(running&&!paused&&p1){if(k==='j')attack(p1,'punch');if(k==='k')attack(p1,'kick');if(k==='l')attack(p1,'special');}
  });
  window.addEventListener('keyup', e=>{keys[e.key.toLowerCase()]=false;});
  document.querySelectorAll('[data-key]').forEach(button=>{
    const key=button.dataset.key;
    const down=e=>{e.preventDefault();keys[key]=true;button.classList.add('active');if(key==='j')attack(p1,'punch');if(key==='k')attack(p1,'kick');if(key==='l')attack(p1,'special');};
    const up=e=>{e.preventDefault();keys[key]=false;button.classList.remove('active');};
    button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('pointerleave',up);
  });
  function attack(f,type){
    if(!running||paused||!f||f.cooldown>0||f.action==='hurt'||f.action==='ko')return;
    const cost=type==='special'?55:0;if(f.meter<cost){if(type==='special')announce('NEED MORE DRIVE');return;}
    f.meter-=cost;f.action=type;f.actionT=type==='punch'?.3:type==='kick'?.48:.58;f.cooldown=type==='punch'?.34:type==='kick'?.56:.78;
    sound(type==='kick'?125:type==='special'?240:250,.06,type==='special'?'sawtooth':'triangle',.035);
  }
  function particlesAt(x,y,color,count=9,power=1){for(let i=0;i<count;i++){let a=Math.random()*Math.PI*2,s=(1+Math.random()*4)*power;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-1,life:.25+Math.random()*.38,max:.63,color,size:1.5+Math.random()*3});}}
  function hit(attacker, target, type){
    const range=type==='punch'?86:type==='kick'?113:160;
    const cx=attacker.x+attacker.face*(type==='punch'?44:type==='kick'?61:70);
    const dist=Math.abs(target.x-cx);
    if(dist>range||Math.abs((FLOOR-target.y)-(FLOOR-attacker.y))>90)return;
    if(target.invuln>0)return;
    const guarding=target.block && target.grounded && target.face===-attacker.face;
    const damage=type==='punch'?7:type==='kick'?12:20;
    target.hp=Math.max(0,target.hp-(guarding?damage*.22:damage));target.invuln=.22;target.hurtT=guarding?.12:.29;
    target.action=guarding?'block':'hurt';target.actionT=guarding?.14:.3;target.vx=attacker.face*(guarding?1.7:type==='punch'?3.5:5.7);target.vy=guarding?0:(type==='special'?-5:type==='kick'?-3.2:-1.5);if(target.vy<0)target.grounded=false;
    attacker.meter=clamp(attacker.meter+(guarding?5:type==='special'?4:12),0,100);target.meter=clamp(target.meter+(guarding?7:4),0,100);
    particlesAt(target.x+attacker.face*18,FLOOR-target.y-92,guarding?'#f9dd69':target.color,type==='special'?20:10,type==='special'?1.5:1);
    shake=guarding?2:type==='special'?8:4;sound(guarding?360:type==='special'?95:150,.1,guarding?'sine':'square',.045);
    if(type==='special'&&!guarding){particlesAt(target.x,FLOOR-target.y-60,attacker.color,22,1.4);}
    if(attacker.human)announce(guarding?'GUARD!':type==='special'?'OVERDRIVE!':'NICE HIT!');
  }
  function updateFighter(f,op,dt){
    f.cooldown=Math.max(0,f.cooldown-dt);f.invuln=Math.max(0,f.invuln-dt);f.actionT=Math.max(0,f.actionT-dt);
    if(f.action==='hurt'&&f.actionT===0)f.action='idle';if(f.action==='block'&&f.actionT===0)f.action='idle';
    f.face=op.x>=f.x?1:-1;
    let move=0;
    if(f.human){move=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);f.block=!!(keys.s||keys.arrowdown);if((keys.w||keys.arrowup||keys[' '])&&f.grounded){f.vy=-10;f.grounded=false;f.action='jump';sound(300,.09,'sine',.025);}}
    else {
      f.aiThink-=dt;const gap=Math.abs(op.x-f.x), facing=op.x>f.x?1:-1;
      if(f.aiThink<=0){f.aiThink=.12+Math.random()*.18;f.aiMove=gap>140?facing:gap<68?-facing:Math.random()>.48?facing:0;f.aiBlock=op.action==='special'&&gap<180&&Math.random()>.28||op.action==='kick'&&gap<125&&Math.random()>.5;}
      move=f.aiMove;f.block=f.aiBlock;
      if(gap<170&&f.cooldown===0&&Math.random()<dt*(gap<100?1.2:.68))attack(f,Math.random()<.48?'punch':'kick');
      if(gap>230&&Math.random()<dt*.55&&f.grounded){f.vy=-9;f.grounded=false;f.action='jump';}
      if(f.hp<34&&f.meter>=55&&gap<160&&f.cooldown===0&&Math.random()<dt*.8)attack(f,'special');
    }
    if(f.action==='hurt'||f.action==='ko')move=0;
    if(f.action==='punch'||f.action==='kick'||f.action==='special')move*=.3;
    f.block=f.block&&f.grounded&&f.action!=='hurt';
    const speed=f.block?70:205;
    f.vx += move*speed*dt; f.vx *= Math.pow(move? .84:.025, dt*60); f.x+=f.vx*dt;
    f.x=clamp(f.x,70,930);
    if(!f.grounded){f.y+=f.vy*dt*60;f.vy+=.48*dt*60;if(f.y>=0){f.y=0;f.vy=0;f.grounded=true;if(f.action==='jump')f.action='idle';}}
    if(Math.abs(f.vx)>15)f.walk+=dt*10;
    if(f.actionT<=0&&(f.action==='punch'||f.action==='kick'||f.action==='special'))f.action='idle';
    if(f.action==='punch'&&f.actionT<.21&&f.actionT>.12&&!f.didHit){f.didHit=true;hit(f,op,'punch');}
    else if(f.action==='kick'&&f.actionT<.32&&f.actionT>.19&&!f.didHit){f.didHit=true;hit(f,op,'kick');}
    else if(f.action==='special'&&f.actionT<.39&&f.actionT>.26&&!f.didHit){f.didHit=true;hit(f,op,'special');}
    if(!['punch','kick','special'].includes(f.action))f.didHit=false;
  }
  function step(dt){
    if(!running||paused)return;
    elapsed+=dt;timeLeft=Math.max(0,timeLeft-dt);ui.timer.textContent=String(Math.ceil(timeLeft)).padStart(2,'0');
    updateFighter(p1,p2,dt);updateFighter(p2,p1,dt);
    // Keep fighters from passing through one another.
    const gap=p2.x-p1.x;if(gap<48){const push=(48-gap)/2;p1.x-=push;p2.x+=push;}
    ui.h1.style.width=`${p1.hp}%`;ui.h2.style.width=`${p2.hp}%`;ui.m1.style.width=`${p1.meter}%`;ui.m2.style.width=`${p2.meter}%`;
    particles.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.vy+=.16;p.life-=dt;});particles=particles.filter(p=>p.life>0);
    shake=Math.max(0,shake-dt*18);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');}
    if(p1.hp<=0||p2.hp<=0||timeLeft<=0)endRound(p1.hp===p2.hp?null:p1.hp>p2.hp?0:1);
  }
  function endRound(winner){
    running=false;const champ=winner===null?(p1.hp>=p2.hp?0:1):winner;if(winner!==null)wins[winner]++;updateScore();
    const final=wins[champ]>=2||roundNo>=3;
    ui.status.textContent=winner===null?'TIME UP':'K.O.';ui.title.textContent=final?(wins[0]===wins[1]?'DRAW!':champ===0?'VOLT WINS':'GLITCH WINS'):(champ===0?'VOLT TAKES IT':'GLITCH TAKES IT');
    ui.sub.textContent=final?'THE UNDERGROUND CIRCUIT':'ROUND '+(roundNo+1)+' // GET READY';
    ui.start.innerHTML=final?'RUN IT BACK <span>↗</span>':'NEXT ROUND <span>↗</span>';
    ui.banner.classList.remove('hidden');sound(final?440:260,.45,'triangle',.05);
    if(final)matchOver=true;else roundNo++;
    ui.start.onclick=null;ui.start.onclick=()=>{if(!final){resetRound();startGame();}else startGame();};
  }

  function line(x1,y1,x2,y2,color,width=6,glow=0){ctx.save();ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle=color;ctx.lineWidth=width;if(glow){ctx.shadowColor=color;ctx.shadowBlur=glow;}ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();ctx.restore();}
  function circle(x,y,r,color,glow=0){ctx.save();ctx.fillStyle=color;if(glow){ctx.shadowColor=color;ctx.shadowBlur=glow;}ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.restore();}
  function drawBackground(){
