    // Neon moon and distant skyline.
    const moon=ctx.createRadialGradient(515,110,5,515,110,90);moon.addColorStop(0,'#f7518870');moon.addColorStop(.32,'#d33e7560');moon.addColorStop(1,'#d33e7500');ctx.fillStyle=moon;ctx.fillRect(405,0,220,220);circle(515,110,43,'#e84e8050');
    ctx.save();ctx.globalAlpha=.35;for(let i=0;i<17;i++){const x=i*68-18,w=34+(i*19)%27,h=60+(i*47)%110,y=FLOOR-h-33;ctx.fillStyle=i%2?'#10192d':'#151b31';ctx.fillRect(x,y,w,h);for(let r=0;r<5;r++)for(let c=0;c<3;c++){if((i*3+r+c)%4===0)continue;ctx.fillStyle=(i+c)%3===0?'#ff648544':'#46e9d344';ctx.fillRect(x+5+c*9,y+8+r*15,3,5);}}ctx.restore();
