    ctx.save();ctx.strokeStyle='#4cebd71b';ctx.lineWidth=1;
    for(let i=0;i<=12;i++){const x=i*W/12;ctx.beginPath();ctx.moveTo(W/2+(x-W/2)*.08,FLOOR);ctx.lineTo(x,H);ctx.stroke();}
    for(let i=1;i<6;i++){let t=i/5, y=FLOOR+t*t*(H-FLOOR);ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}ctx.restore();
    ctx.save();ctx.globalAlpha=.55;ctx.fillStyle='#47f4db';ctx.fillRect(0,FLOOR,W,1);ctx.shadowColor='#47f4db';ctx.shadowBlur=13;ctx.fillRect(0,FLOOR,W,1);ctx.restore();
    // Moving scanlines and edge vignette.
    ctx.fillStyle='#a7c7ff08';for(let y=(elapsed*32)%8;y<H;y+=8)ctx.fillRect(0,y,W,1);
    const vignette=ctx.createRadialGradient(W/2,H/2,120,W/2,H/2,570);vignette.addColorStop(.5,'#00000000');vignette.addColorStop(1,'#060914a8');ctx.fillStyle=vignette;ctx.fillRect(0,0,W,H);
    ctx.save();ctx.font='500 10px monospace';ctx.fillStyle='#8c9bb93b';ctx.fillText('NIGHT SHIFT  //  SECTOR 09',24,28);ctx.textAlign='right';ctx.fillText('NO RULES · NO REFEREE',976,28);ctx.restore();
  }
  function drawFighter(f){
    const x=f.x, base=FLOOR-f.y, face=f.face, moving=Math.abs(f.vx)>22, t=f.walk;
    const bob=f.grounded?(moving?Math.abs(Math.sin(t))*3:Math.sin(elapsed*3+(f.human?0:1))*.9):0;
    let action=f.action, crouch=f.block?.2:0;
