    // Head, face visor, and headband.
    circle(x,headY,15,'#0c1020',13);circle(x,headY,12.5,f.color,10);circle(x,headY,9,'#171c2d');
    line(x+face*2,headY-1,x+face*10,headY-1,f.human?'#a6fff1':'#ffc0d0',3,8);
    line(x-face*10,headY-9,x+face*9,headY-9,f.color,3,9);
    // Torso emblem.
    circle(x+face*2,base-91+crouch*13,3,'#f4f4f7',4);
    if(action==='special'){
      ctx.save();ctx.globalAlpha=.7;ctx.strokeStyle=f.color;ctx.lineWidth=2;ctx.shadowColor=f.color;ctx.shadowBlur=20;ctx.beginPath();ctx.arc(x,base-82,45+Math.sin(elapsed*27)*6,elapsed*3,elapsed*3+Math.PI*1.35);ctx.stroke();ctx.restore();
    }
    if(f.invuln>0&&Math.floor(elapsed*30)%2===0){ctx.save();ctx.globalAlpha=.35;ctx.fillStyle='#fff';ctx.beginPath();ctx.ellipse(x,base-79,23,73,0,0,Math.PI*2);ctx.fill();ctx.restore();}
    ctx.save();ctx.font='700 9px monospace';ctx.textAlign='center';ctx.fillStyle=f.color;ctx.shadowColor=f.color;ctx.shadowBlur=8;ctx.fillText(f.name,x,FLOOR+26);ctx.restore();
  }
  function draw(){
    ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);drawBackground();
    if(p1&&p2){drawFighter(p1);drawFighter(p2);}
    particles.forEach(p=>{ctx.save();ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=11;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();ctx.restore();});
    ctx.restore();
  }
  function frame(now){const dt=Math.min(.034,(now-last)/1000||0);last=now;if(!paused){step(dt);if(!running)elapsed+=dt;}draw();requestAnimationFrame(frame);}
  requestAnimationFrame(frame);
})();

