(() => {
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const W = 1000, H = 520, FLOOR = 421;
  const ui = {h1:document.getElementById('health1'),h2:document.getElementById('health2'),m1:document.getElementById('meter1'),m2:document.getElementById('meter2'),timer:document.getElementById('timer'),status:document.getElementById('statusText'),banner:document.getElementById('roundBanner'),title:document.getElementById('bannerTitle'),sub:document.getElementById('bannerSub'),start:document.getElementById('startButton'),pause:document.getElementById('pauseOverlay'),toast:document.getElementById('toast'),score:document.getElementById('roundScore')};
  const keys=Object.create(null), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  let p1,p2,running=false,paused=false,matchOver=false,nextRound=false,timeLeft=60,wins=[0,0],roundNo=1,last=0,elapsed=0,shake=0,toastTimer=0,particles=[],audioCtx=null,soundOn=true;
  const fighter=(x,face,color,glow,name,human)=>({x,y:0,vx:0,vy:0,face,color,glow,name,human,hp:100,meter:0,grounded:true,action:'idle',actionT:0,cooldown:0,invuln:0,hurtT:0,block:false,walk:0,aiThink:0,aiMove:0,aiBlock:0});
  function updateScore(){ui.score.innerHTML=`ROUNDS <b>${wins[0]}</b> — <b>${wins[1]}</b>`;}
  function resetRound(){p1=fighter(295,1,'#4df3dc','#38ffe5','VOLT',true);p2=fighter(705,-1,'#ff5488','#ff4b80','GLITCH',false);timeLeft=60;particles=[];shake=0;ui.h1.style.width=ui.h2.style.width='100%';ui.m1.style.width=ui.m2.style.width='0%';ui.timer.textContent='60';ui.status.textContent='FIGHT!';updateScore();}
  resetRound();
  function sound(freq=180,duration=.08,type='sine',volume=.04){if(!soundOn)return;try{audioCtx||=new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(50,freq*.55),audioCtx.currentTime+duration);g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch(_){}}
  document.getElementById('soundToggle').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.querySelector('b').textContent=soundOn?'ON':'OFF';e.currentTarget.querySelector('.sound-icon').textContent=soundOn?'♪':'×';if(soundOn)sound(520,.07,'sine',.025);});
  function announce(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=.75;}
  function startGame(){if(matchOver){wins=[0,0];roundNo=1;matchOver=false;resetRound();ui.title.textContent='READY?';ui.sub.textContent='FIRST TO TWO ROUNDS';ui.start.innerHTML='ENTER THE ARENA <span>↗</span>';}ui.banner.classList.add('hidden');running=true;paused=false;last=performance.now();sound(370,.12,'triangle',.035);announce('FIGHT!');}
  ui.start.addEventListener('click',()=>{if(nextRound){nextRound=false;resetRound();startGame();}else startGame();});
  function togglePause(){if(!running||matchOver)return;paused=!paused;ui.pause.classList.toggle('hidden',!paused);if(!paused)last=performance.now();}
  window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup','arrowdown'].includes(k))e.preventDefault();if(k==='escape'){togglePause();return;}if(k==='enter'&&!running){startGame();return;}keys[k]=true;if(running&&!paused){if(k==='j')attack(p1,'punch');if(k==='k')attack(p1,'kick');if(k==='l')attack(p1,'special');}});
  window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});
  document.querySelectorAll('[data-key]').forEach(button=>{const key=button.dataset.key;const down=e=>{e.preventDefault();keys[key]=true;button.classList.add('active');if(key==='j')attack(p1,'punch');if(key==='k')attack(p1,'kick');if(key==='l')attack(p1,'special');};const up=e=>{e.preventDefault();keys[key]=false;button.classList.remove('active');};button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('pointerleave',up);});
  function attack(f,type){if(!running||paused||!f||f.cooldown>0||f.action==='hurt'||f.action==='ko')return;const cost=type==='special'?55:0;if(f.meter<cost){if(type==='special')announce('NEED MORE DRIVE');return;}f.meter-=cost;f.action=type;f.actionT=type==='punch'?.3:type==='kick'?.48:.58;f.cooldown=type==='punch'?.34:type==='kick'?.56:.78;f.didHit=false;sound(type==='kick'?125:type==='special'?240:250,.06,type==='special'?'sawtooth':'triangle',.035);}
  function particlesAt(x,y,color,count=9,power=1){for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,s=(1+Math.random()*4)*power;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-1,life:.25+Math.random()*.38,max:.63,color,size:1.5+Math.random()*3});}}
  function hit(attacker,target,type){const range=type==='punch'?86:type==='kick'?113:160,cx=attacker.x+attacker.face*(type==='punch'?44:type==='kick'?61:70);if(Math.abs(target.x-cx)>range||Math.abs(target.y-attacker.y)>90||target.invuln>0)return;const guarding=target.block&&target.grounded&&target.face===-attacker.face,damage=type==='punch'?7:type==='kick'?12:20;target.hp=Math.max(0,target.hp-(guarding?damage*.22:damage));target.invuln=.22;target.hurtT=guarding?.12:.29;target.action=guarding?'block':'hurt';target.actionT=guarding?.14:.3;target.vx=attacker.face*(guarding?1.7:type==='punch'?3.5:5.7);target.vy=guarding?0:(type==='special'?-5:type==='kick'?-3.2:-1.5);if(target.vy<0)target.grounded=false;attacker.meter=clamp(attacker.meter+(guarding?5:type==='special'?4:12),0,100);target.meter=clamp(target.meter+(guarding?7:4),0,100);particlesAt(target.x+attacker.face*18,FLOOR-target.y-92,guarding?'#f9dd69':target.color,type==='special'?20:10,type==='special'?1.5:1);shake=guarding?2:type==='special'?8:4;sound(guarding?360:type==='special'?95:150,.1,guarding?'sine':'square',.045);if(type==='special'&&!guarding)particlesAt(target.x,FLOOR-target.y-60,attacker.color,22,1.4);if(attacker.human)announce(guarding?'GUARD!':type==='special'?'OVERDRIVE!':'NICE HIT!');}
  function updateFighter(f,op,dt){f.cooldown=Math.max(0,f.cooldown-dt);f.invuln=Math.max(0,f.invuln-dt);f.actionT=Math.max(0,f.actionT-dt);if((f.action==='hurt'||f.action==='block')&&f.actionT===0)f.action='idle';f.face=op.x>=f.x?1:-1;let move=0;
    if(f.human){move=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);f.block=!!(keys.s||keys.arrowdown);if((keys.w||keys.arrowup||keys[' '])&&f.grounded){f.vy=-10;f.grounded=false;f.action='jump';sound(300,.09,'sine',.025);}}
